#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// OpenSSL internal symbols (not in public headers)
extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                           const unsigned int key[8], const unsigned int counter[4]);
extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);
extern size_t Poly1305_ctx_size(void);

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9; }

#define N (40*1024*1024)

int main(){
    unsigned char *pt = malloc(N), *ct = malloc(N);
    unsigned char key[32], nonce[12];
    for(int i=0;i<32;i++) key[i]=i;
    for(int i=0;i<12;i++) nonce[i]=i;
    for(size_t i=0;i<N;i++) pt[i]=i&0xff;

    unsigned int keyw[8];
    memcpy(keyw, key, 32);
    unsigned int counter[4] = {1,0,0,0}; // counter=1 (block 0 is poly key)

    // single-threaded ChaCha20_ctr32
    double best=1e9;
    for(int r=0;r<5;r++){ double t0=now(); ChaCha20_ctr32(ct, pt, N, keyw, counter); double t1=now(); if(t1-t0<best)best=t1-t0; }
    printf("ChaCha20_ctr32 single: %.4f ms -> %.2f GB/s\n", best*1e3, N/best/1e9);

    // Poly1305 single-threaded
    size_t ctxsz = Poly1305_ctx_size();
    void *ctx = malloc(ctxsz);
    unsigned char pkey[32]; for(int i=0;i<32;i++) pkey[i]=i;
    best=1e9;
    for(int r=0;r<5;r++){ double t0=now(); Poly1305_Init(ctx, pkey); Poly1305_Update(ctx, ct, N); unsigned char mac[16]; Poly1305_Final(ctx, mac); double t1=now(); if(t1-t0<best)best=t1-t0; }
    printf("Poly1305 single: %.4f ms -> %.2f GB/s\n", best*1e3, N/best/1e9);

    free(pt); free(ct); free(ctx);
    return 0;
}
EOF
