{"command":"cd "$(pwd)"; cat > mt.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                           const unsigned int key[8], const unsigned int counter[4]);

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9; }

#define N (40*1024*1024)
#define NT 12

typedef struct { unsigned char *out, *in; size_t len; unsigned int key[8]; unsigned int counter[4]; } job_t;

void* worker(void* a){
    job_t* j = (job_t*)a;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

int main(){
    unsigned char *pt = malloc(N), *ct = malloc(N);
    unsigned char key[32];
    for(int i=0;i<32;i++) key[i]=i;
    for(size_t i=0;i<N;i++) pt[i]=i&0xff;
    unsigned int keyw[8]; memcpy(keyw, key, 32);

    // single thread baseline
    unsigned int ctr[4] = {1,0,0,0};
    double t0=now(); ChaCha20_ctr32(ct, pt, N, keyw, ctr); double t1=now();
    printf("single: %.3f ms -> %.2f GB/s\n", (t1-t0)*1e3, N/(t1-t0)/1e9);

    // multithreaded
    for(int nt=1; nt<=12; nt++){
        pthread_t th[NT]; job_t jobs[NT];
        size_t chunk = N/nt;
        double best=1e9;
        for(int r=0;r<5;r++){
            double s=now();
            for(int i=0;i<nt;i++){
                jobs[i].out = ct + i*chunk;
                jobs[i].in = pt + i*chunk;
                jobs[i].len = (i==nt-1)? (N - i*chunk) : chunk;
                memcpy(jobs[i].key, keyw, 32);
                jobs[i].counter[0] = 1 + (i*chunk)/64;
                jobs[i].counter[1]=jobs[i].counter[2]=jobs[i].counter[3]=0;
                pthread_create(&th[i], NULL, worker, &jobs[i]);
            }
            for(int i=0;i<nt;i++) pthread_join(th[i], NULL);
            double e=now();
            if(e-s<best) best=e-s;
        }
        printf("nt=%d: %.3f ms -> %.2f GB/s\n", nt, best*1e3, N/best/1e9);
    }
    free(pt); free(ct);
    return 0;
}
EOF
